  align-items: center;
}

.nav-menu a {
  color: var(--text-muted);
  position: relative;
  transition: color 0.18s ease, transform 0.12s ease;
  padding: 8px 10px;
  border-radius: 8px;
}

.nav-menu a:hover,
.nav-menu a.active {
  color: var(--text);
  transform: translateY(-2px);
  background: rgba(37,99,235,0.06);
}

.nav-menu a.active::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 100%;
  height: 3px;
  background: var(--primary);
  border-radius: 999px;
}

.nav-toggle,
.theme-toggle {
  display: none;
  border: none;
  background: transparent;
  font-size: 1.3rem;
  cursor: pointer;
  color: var(--text);
}

.main,
footer,
section {
