  margin-bottom: 16px;
}

.eyebrow {
  display: inline-block;
  margin-bottom: 16px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.78rem;
}

.hero-copy p,
.stock-description,
.page-intro p,
.contact-hero p {
  max-width: 720px;
  color: var(--text-muted);
  line-height: 1.75;
}

.hero-actions,
.cta-group,
.watchlist-controls,
.form-actions {
  display: flex;
