}

.market-card:hover,
.testimonial-card:hover,
.feature-card:hover,
.index-card:hover,
.market-panel:hover,
.stock-summary-card:hover,
.detail-card:hover,
.mini-card:hover,
.contact-card:hover,
.watchlist-card:hover {
  transform: translateY(-4px);
