  if (buyButton) {
    buyButton.addEventListener('click', () => {
      showToast(`Buy order placed for ${stockName}.`);
    });
  }

  if (sellButton) {
    sellButton.addEventListener('click', () => {
      showToast(`Sell order placed for ${stockName}.`);
    });
