edits.text:
@media (max-width: 768px) {
  .hero-section,
  .stock-hero,
  .portfolio-hero,
  .contact-hero,
  .page-intro {
    grid-template-columns: 1fr;
  }

  .info-grid,
  .feature-grid,
  .testimonial-grid,
  .index-grid,
  .trending-grid,
  .portfolio-cards,
  .stock-detail-cards,
  .watchlist-grid,
  .market-sections,
  .form-row {
    grid-template-columns: 1fr;
  }

  .nav-menu {
    width: 100%;
  }
}

@media (max-width: 1024px) {
  .hero-section,
  .stock-hero,
  .portfolio-hero,
  .contact-hero,
  .page-intro {
    gap: 24px;
  }
}

@media (max-width: 1440px) {
  .navbar,
  .main,
  footer {
    width: min(100%, calc(100% - 32px));
  }
}

/* Additional responsive refinements */

@media (max-width: 768px) {
  .navbar {
    padding: 10px 14px;
    position: sticky;
    top: 8px;
    z-index: 1200;
    background: var(--surface);
  }

  .brand a { font-size: 1.25rem; }

  .nav-toggle {
    display: inline-flex;
    font-size: 1.25rem;
  }

  .nav-menu {
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
    margin-top: 8px;
    padding: 0 12px;
    max-height: 0;
    overflow: hidden;
    opacity: 0;
    transition: max-height 260ms ease, opacity 240ms ease;
  }

  .nav-menu.open {
    max-height: 420px;
    opacity: 1;
  }

  .nav-menu a { padding: 10px 8px; }

  .theme-toggle { order: 3; }

  .hero-copy h1 { font-size: 1.6rem; }
  .section-heading h2 { font-size: 1.2rem; }
  .testimonial-grid, .feature-grid { grid-template-columns: 1fr; }
}

/* Small-screen usability */
@media (max-width: 768px) {
  .cta-group { flex-direction: column; gap: 12px; }
  .cta-group .btn { width: 100%; }

  .watchlist-grid, .index-grid, .trending-grid {
    grid-template-columns: 1fr !important;
  }

  .watchlist-card {
    padding: 16px;
  }

  .watchlist-card button {
    width: 100%;
    margin-top: 8px;
  }

  .contact-form {
    padding: 18px;
  }

  .contact-form input,
  .contact-form textarea {
    padding: 12px;
    font-size: 0.95rem;
  }

  .table-row { grid-template-columns: 1fr 1fr; gap: 8px; }
  .table-row .table-header { display: none; }

  .stock-summary-card { margin-top: 18px; }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .hero-copy h1 { font-size: 2.2rem; }
  .brand a { font-size: 1.4rem; }
  .index-grid, .trending-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-grid { grid-template-columns: repeat(2, minmax(180px,1fr)); }
}

@media (min-width: 1025px) and (max-width: 1440px) {
  .hero-copy h1 { font-size: clamp(2.2rem, 3vw, 2.8rem); }
  .index-grid { grid-template-columns: repeat(3, 1fr); }
  .trending-grid { grid-template-columns: repeat(3, 1fr); }
  .navbar { width: min(1000px, calc(100% - 40px)); }
}

@media (min-width: 1441px) {
  .navbar { width: 1120px; }
}

:root {
  --bg: #f5f7fb;
  --surface: #ffffff;
  --surface-strong: #ffffff;
  --text: #1f2937;
  --text-muted: #6b7280;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --success: #16a34a;
  --danger: #dc2626;
  --border: #e5e7eb;
  --shadow: 0 24px 80px rgba(15, 23, 42, 0.08);
}

body.dark {
  --bg: #0f172a;
  --surface: #111827;
  --surface-strong: #0f172a;
  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --primary: #5b8cff;
  --primary-hover: #3b82f6;
  --success: #22c55e;
  --danger: #f97316;
  --border: #334155;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.28);
}

/* Load Inter font as primary */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Inter, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: background 0.35s ease, color 0.35s ease;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea {
  font-family: inherit;
}

.navbar {
  width: min(1120px, calc(100% - 40px));
  margin: 12px auto;
  padding: 12px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(15,23,42,0.04);
}

.brand a {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

.brand a:hover{color:var(--primary)}

.nav-menu {
  display: flex;
  gap: 20px;
  align-items: center;
}

.nav-menu a {
  color: var(--text-muted);
  position: relative;
  transition: color 0.18s ease, transform 0.12s ease;
  padding: 8px 10px;
  border-radius: 8px;
}

.nav-menu a:hover,
.nav-menu a.active {
  color: var(--text);
  transform: translateY(-2px);
  background: rgba(37,99,235,0.06);
}

.nav-menu a.active::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 100%;
  height: 3px;
  background: var(--primary);
  border-radius: 999px;
}

.nav-toggle,
.theme-toggle {
  border: none;
  background: transparent;
  font-size: 1.3rem;
  cursor: pointer;
  color: var(--text);
}

.theme-toggle {
  display: inline-flex;
}

.nav-toggle {
  display: none;
}

body.menu-open {
  overflow: hidden;
}

.navbar { position: relative; z-index: 1100; }

.main,
footer,
section {
  width: min(1120px, calc(100% - 40px));
  margin: 0 auto;
}

.hero-section,
.stock-hero,
.portfolio-hero,
.contact-hero,
.page-intro {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 36px;
  align-items: center;
  padding: 40px 0 20px;
}

.hero-copy h1,
.page-intro h1,
.stock-hero h1,
.contact-hero h1 {
  font-size: clamp(2rem, 3.2vw, 3.2rem);
  line-height: 1.05;
  margin-bottom: 16px;
}

.eyebrow {
  display: inline-block;
  margin-bottom: 16px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.78rem;
}

.hero-copy p,
.stock-description,
.page-intro p,
.contact-hero p {
  max-width: 720px;
  color: var(--text-muted);
  line-height: 1.75;
}

.hero-actions,
.cta-group,
.watchlist-controls,
.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 24px;
}

.btn {
  border: none;
  border-radius: 999px;
  padding: 14px 24px;
  cursor: pointer;
  font-weight: 600;
  transition: transform 0.2s ease, background 0.2s ease;
}

/* Make buttons more tappable on smaller screens */
@media (max-width: 768px) {
  .btn { padding: 14px 18px; font-size: 1rem; }
  .btn-primary, .btn-secondary { width: auto; }
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-hover);
}

.btn-secondary {
  background: rgba(37, 99, 235, 0.08);
  color: var(--text);
}

.btn:hover {
  transform: translateY(-1px);
}

.market-card,
.testimonial-card,
.feature-card,
.index-card,
.market-panel,
.stock-summary-card,
.detail-card,
.mini-card,
.holdings-table,
.contact-card,
.watchlist-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 18px;
  box-shadow: var(--shadow);
  padding: 20px 22px;
  transition: transform 0.2s ease, background 0.35s ease, border-color 0.35s ease;
}

.market-card:hover,
.testimonial-card:hover,
.feature-card:hover,
.index-card:hover,
.market-panel:hover,
.stock-summary-card:hover,
.detail-card:hover,
.mini-card:hover,
.contact-card:hover,
.watchlist-card:hover {
  transform: translateY(-4px);
}

.market-card__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
  font-weight: 600;
}

.market-card__body p {
  color: var(--text-muted);
  line-height: 1.7;
}

.info-grid,
.feature-grid,
.testimonial-grid,
.index-grid,
.trending-grid,
.portfolio-cards,
.holdings-table,
.watchlist-grid {
  display: grid;
  gap: 20px;
}

.info-grid {
  grid-template-columns: repeat(3, minmax(220px, 1fr));
}

.feature-grid {
  grid-template-columns: repeat(4, minmax(210px, 1fr));
}

.testimonial-grid {
  grid-template-columns: repeat(3, minmax(240px, 1fr));
}

.index-grid {
  grid-template-columns: repeat(3, minmax(220px, 1fr));
}

.trending-grid {
  grid-template-columns: repeat(3, minmax(240px, 1fr));
}

.portfolio-cards {
  grid-template-columns: repeat(3, minmax(180px, 1fr));
}

.watchlist-grid {
  grid-template-columns: repeat(3, minmax(240px, 1fr));
}

.feature-card h3,
.testimonial-card h4,
.market-panel h3,
.detail-card h4,
.mini-card h4 {
  margin-bottom: 14px;
}

.testimonial-card p {
  color: var(--text-muted);
  margin-bottom: 22px;
  line-height: 1.75;
}

.testimonial-card span,
.market-summary div h3 {
  color: var(--text-muted);
}

.section-heading {
  margin-bottom: 26px;
}

.section-heading h2 {
  font-size: clamp(1.6rem, 2.1vw, 2.2rem);
  line-height: 1.1;
}

.empty-state{padding:18px;color:var(--text-muted)}

.market-summary {
  margin-top: 24px;
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.market-summary div {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 22px;
  padding: 22px;
}

.market-summary h3,
.stock-summary-card h3,
.holdings-section h2,
.trending-section h2,
.stock-hero h1,
.contact-hero h1 {
  margin-bottom: 12px;
}

.status {
  font-weight: 700;
}

.up {
  color: var(--success);
}

.down {
  color: var(--danger);
}

.stock-summary-card ul {
  list-style: none;
  display: grid;
  gap: 12px;
}

.stock-summary-card li {
  display: flex;
  justify-content: space-between;
  color: var(--text-muted);
}

.stock-detail-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(220px, 1fr));
  gap: 20px;
  margin: 32px 0;
}

.detail-card p,
.mini-card p {
  font-size: 1.1rem;
  margin-top: 10px;
}

.holdings-table {
  border-radius: 28px;
  overflow: hidden;
}

.table-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1.5fr 1fr;
  gap: 10px;
  padding: 18px 20px;
  align-items: center;
}

.table-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  font-weight: 700;
}

.table-row:not(.table-header) {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.stock-hero p,
.portfolio-value,
.stock-description,
.watchlist-section p,
.contact-card p,
.contact-form label,
.form-status {
  color: var(--text-muted);
}

.portfolio-value {
  font-size: 2.6rem;
  font-weight: 700;
  margin: 20px 0 0;
}

.watchlist-controls {
  justify-content: space-between;
  gap: 16px;
}

.watchlist-controls input,
.search-bar input,
.contact-form input,
.contact-form textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 16px 18px;
  background: var(--surface);
  color: var(--text);
}

.search-bar input {
  width: 100%;
}

.contact-form {
  display: grid;
  gap: 18px;
  padding: 32px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 28px;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.contact-form label {
  display: grid;
  gap: 10px;
  font-weight: 600;
}

.form-actions {
  align-items: center;
}

.form-status {
  font-size: 0.95rem;
}

.contact-card {
  max-width: 420px;
}

.site-footer {
  width: min(1120px, calc(100% - 40px));
  margin: 60px auto 40px;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  border-top: 1px solid var(--border);
