}

.watchlist-card .watchlist-card__meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.watchlist-card button {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text);
  width: 100%;
}

/* Ensure watchlist remove button is easy to tap on tablets */
@media (min-width: 769px) and (max-width: 1024px) {
  .watchlist-card button { width: 48%; }
}

.market-panel {
  border-radius: 28px;
  padding: 24px;
